typedef enum {
    R_X86_64_NONE,
    R_X86_64_64,    // Absolute 64-bit
    R_X86_64_PC32,  // PC-relative 32-bit
    R_X86_64_GLOB_DAT
} RelocType;

struct RelocationEntry {
    uint64_t r_offset;  // Address in section where fixup occurs
    uint32_t r_symbol;  // Index of target symbol in Symbol Table
    RelocType r_type;   // Type of modification required
    int64_t r_addend;   // Constant value added to address calculation
};

// Loader uses: *(r_offset) = target_addr + r_addend + adjustment
// where target_addr is derived from r_symbol.
